-- Cardoso Marketing Hub — projeto "Conferência de Embalagens" (importado do Monday.com)
-- Roda uma vez no SQL Editor, depois de 0001..0015 já terem rodado.

alter table public.tasks add column product_id uuid references public.products (id) on delete set null;
create index on public.tasks (product_id);

values (
  gen_random_uuid(),
  (select id from public.brands where key = 'cardoso'),
  'Conferência de Embalagens',
  'Acompanhamento do desenvolvimento e aprovação de embalagens (importado do Monday)',
  'active',
  'high',
  'Embalagens',
  '2026-03-16',
  'Acompanhar o desenvolvimento, correção e aprovação de embalagens de produtos, com status sincronizado automaticamente na Lista de Produtos.'
) returning id;

